sections.css:
.mono{font-family: "IBM Plex Mono", monospace;}
.display{font-weight: 900;}
.aero{position: relative; overflow: hidden; height: 40px; padding: 0px 16px; border-radius: 3px; border: 1px solid rgba(0, 0, 0, 0.12); background: linear-gradient(rgba(255, 255, 255, 0.98), rgba(246, 246, 246, 0.86)); color: rgba(0, 0, 0, 0.84); text-transform: uppercase; font-size: 10px; cursor: pointer; transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.35s, box-shadow 0.35s; box-shadow: rgba(255, 255, 255, 0.9) 0px 1px 0px inset;}
.aero::after{content: ""; position: absolute; inset: 0px; opacity: 0; background: linear-gradient(90deg, transparent, rgba(74, 145, 255, 0.26), transparent); transition: 0.35s; pointer-events: none;}
.aero:hover{transform: translateY(-2px); border-color: rgba(74, 145, 255, 0.4); box-shadow: rgba(255, 255, 255, 0.96) 0px 1px 0px inset, rgba(74, 145, 255, 0.14) 0px 0px 0px 1px;}
.aero:hover::after{opacity: 1;}
.hero{position: relative; min-height: 100svh; display: grid; grid-template-columns: 1fr; background: var(--white); padding-top: 64px; overflow: hidden;}
.hero-grid{position: relative; z-index: 10; width: min(1600px, 100% - 28px); margin: 0px auto; min-height: calc(-64px + 100svh); display: grid; grid-template-columns: 1fr 1fr; align-items: stretch;}
.hero-copy{position: relative; z-index: 4; padding: 72px 24px 48px 0px; display: flex; align-items: center; justify-content: flex-start; background: transparent; border-right-width: medium; border-right-style: none; border-right-color: currentcolor;}
.hero-side{position: relative; background: transparent; overflow: visible; min-height: calc(-64px + 100svh);}
.video-shell{position: absolute; inset: 0px; z-index: 1; overflow: hidden; mask-image: linear-gradient(to right, transparent 0%, transparent 20%, black 55%, black 100%); filter: saturate(1.06) contrast(1.04) brightness(0.96);}
.hero-copy-inner{width: 100%; max-width: 640px; padding: 18px 18px 18px 0px;}
.eyebrow{display: inline-flex; align-items: center; gap: 10px; padding: 10px 14px; border-radius: 3px; border: 1px solid rgba(0, 0, 0, 0.08); background: rgba(255, 255, 255, 0.72); text-transform: uppercase; font-size: 10px; color: rgba(0, 0, 0, 0.62); backdrop-filter: blur(8px);}
.eyebrow span{width: 8px; height: 8px; background: var(--blue); display: inline-block;}
.hero-title{margin-top: 22px; font-size: clamp(4.6rem, 8.8vw, 8.8rem); line-height: 0.86; color: rgb(8, 8, 8); text-transform: none;}
.hero-title .line{overflow: hidden; position: relative;}
.hero-title .line span{display: inline-block; transform: translateY(100%); opacity: 0; filter: blur(8px);}
.typed{animation: 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0s 1 normal forwards running typedIn;}
.hero-copy-text{margin-top: 24px; max-width: 560px; font-size: 16px; line-height: 2; color: rgba(0, 0, 0, 0.72);}
.hero-specs{margin-top: 20px; display: flex; flex-wrap: wrap; gap: 10px;}
.hero-specs span{padding: 10px 12px; border: 1px solid rgba(0, 0, 0, 0.08); background: rgba(255, 255, 255, 0.84); border-radius: 3px; text-transform: uppercase; font-size: 10px; color: rgba(0, 0, 0, 0.62);}
.hero-actions{margin-top: 26px; display: flex; gap: 12px; flex-wrap: wrap;}
.hero-actions button{height: 46px; padding: 0px 18px; border-radius: 3px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; cursor: pointer; font-size: 10px; text-transform: uppercase;}
.video-shell{position: absolute; inset: 0px -12% 0px -8%; z-index: 2; overflow: hidden; mask: url("#dataPulseMask"); filter: saturate(1.06) contrast(1.04) brightness(0.96);}
.video-shell video{width: 100%; height: 100%; object-fit: cover; transform: scale(1.06); will-change: transform;}
.video-shell::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at 18% 20%, rgba(255, 255, 255, 0.18), transparent 16%), radial-gradient(circle at 65% 28%, rgba(77, 143, 255, 0.2), transparent 14%), linear-gradient(rgba(255, 255, 255, 0.08), rgba(0, 0, 0, 0.18)); z-index: 2; pointer-events: none;}
.video-shell::after{content: ""; position: absolute; inset: -2%; background: linear-gradient(90deg, rgba(255, 255, 255, 0.22), transparent 24%); pointer-events: none; mix-blend-mode: screen;}
.ticker-stack{position: absolute; inset: 20px 18px 20px auto; z-index: 6; width: min(360px, 46%); display: flex; flex-direction: column; gap: 10px;}
.ticker{padding: 14px 16px; background: rgba(255, 255, 255, 0.1); border: 1px solid rgba(255, 255, 255, 0.12); backdrop-filter: blur(40px) brightness(1.1); color: white; border-radius: 3px; box-shadow: rgba(255, 255, 255, 0.1) 0px 1px 0px inset;}
.ticker .top{display: flex; justify-content: space-between; gap: 16px; align-items: center; text-transform: uppercase; font-size: 10px; color: black;}
.ticker .value{margin-top: 10px; font-size: 28px; line-height: 1; color: rgb(5, 5, 5);}
.ticker .small{margin-top: 8px; font-family: "IBM Plex Mono", monospace; font-size: 13px; line-height: 1.7; color: black;}
@media (max-width: 1180px){.hero-grid{grid-template-columns: 1fr;}}
@media (max-width: 1180px){.hero-copy{border-right-width: medium; border-right-style: none; border-right-color: currentcolor; border-bottom: 1px solid rgba(0, 0, 0, 0.08);}}
@media (max-width: 1180px){.hero-side{min-height: 72vh;}}
@media (max-width: 760px){.hero-grid{width: min(100% - 18px, 1600px);}}
@media (max-width: 760px){.hero-copy{padding-top: 36px;}}
@media (max-width: 760px){.hero-copy-inner{padding-left: 0px; padding-right: 0px;}}
@media (max-width: 760px){.hero-title{font-size: clamp(3.2rem, 14vw, 6.2rem);}}
h1{font-size: inherit; font-weight: inherit;}
button{font-family: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-size: 100%; font-weight: inherit; line-height: inherit; letter-spacing: inherit; color: inherit; margin: 0px; padding: 0px;}
button{text-transform: none;}
button{appearance: button; background-color: transparent; background-image: none;}
h1, p{margin: 0px;}
button{cursor: pointer;}
video{display: block; vertical-align: middle;}
video{max-width: 100%; height: auto;}

.mono{font-family: "IBM Plex Mono", monospace;}
.display{font-weight: 900;}
.section{padding: 110px 0px;}
.shell{width: min(1600px, 100% - 28px); margin: 0px auto;}
.section-h{display: flex; justify-content: space-between; gap: 22px; align-items: flex-end; margin-bottom: 26px;}
.section-h h2{font-size: clamp(2.6rem, 5.2vw, 5.8rem); line-height: 0.88; color: rgb(9, 9, 9);}
.section-h p{max-width: 430px; color: rgba(0, 0, 0, 0.66); line-height: 1.95;}
.dual-stream{position: relative; display: grid; grid-template-columns: 0.45fr 0.55fr; gap: 18px; align-items: stretch;}
.ledger-panel{padding: 38px; background: linear-gradient(rgba(255, 255, 255, 0.95), rgba(248, 248, 248, 0.84)); border: 1px solid rgba(0, 0, 0, 0.08); border-radius: 3px;}
.ledger-panel .label{text-transform: uppercase; font-size: 10px; color: rgba(0, 0, 0, 0.54);}
.ledger-panel h3{margin-top: 16px; font-size: clamp(2rem, 4vw, 4.3rem); line-height: 0.9; color: rgb(5, 5, 5);}
.ledger-panel p{margin-top: 18px; line-height: 2; color: rgba(0, 0, 0, 0.68); max-width: 52ch;}
.audit-list{margin-top: 22px; border-top: 1px solid rgba(0, 0, 0, 0.08);}
.audit-row{display: grid; grid-template-columns: auto 1fr auto; gap: 14px; align-items: center; padding: 14px 0px; border-bottom: 1px solid rgba(0, 0, 0, 0.08); font-family: "IBM Plex Mono", monospace; font-size: 11px; text-transform: uppercase; color: rgba(0, 0, 0, 0.7);}
.audit-row strong{color: rgb(0, 0, 0); font-family: inherit;}
.monitor{position: relative; overflow: hidden; border-radius: 3px; border: 1px solid rgba(0, 0, 0, 0.08); background: linear-gradient(rgba(255, 255, 255, 0.9), rgba(245, 247, 250, 0.82)); min-height: 580px; display: grid; grid-template-columns: 1fr 1fr;}
.monitor::before{content: ""; position: absolute; inset: 0px; background: linear-gradient(rgba(255, 255, 255, 0.42), transparent 20%), linear-gradient(90deg, rgba(74, 143, 255, 0.08), transparent 52%); pointer-events: none;}
.monitor .pane{padding: 22px; border-right: 1px solid rgba(0, 0, 0, 0.08);}
.monitor .pane:last-child{border-right-width: medium; border-right-style: none; border-right-color: currentcolor;}
.pane-head{display: flex; justify-content: space-between; align-items: center; gap: 14px; text-transform: uppercase; font-size: 10px; color: rgba(0, 0, 0, 0.55);}
.box{margin-top: 16px; padding: 18px; border: 1px solid rgba(0, 0, 0, 0.08); background: rgba(255, 255, 255, 0.9); border-radius: 3px;}
.box .name{text-transform: uppercase; font-size: 10px; color: rgba(0, 0, 0, 0.5);}
.box .amount{margin-top: 10px; font-size: 34px; color: rgb(5, 5, 5);}
.box .desc{margin-top: 10px; color: rgba(0, 0, 0, 0.66); line-height: 1.85; font-size: 14px;}
.mini-graph{margin-top: 18px; width: 100%; height: 160px; border: 1px solid rgba(0, 0, 0, 0.08); background: linear-gradient(rgba(255, 255, 255, 0.96), rgba(246, 248, 251, 0.86)); border-radius: 3px; padding: 16px;}
.metrics{margin-top: 18px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px;}
.metric{padding: 16px; border: 1px solid rgba(0, 0, 0, 0.08); background: rgba(255, 255, 255, 0.92); border-radius: 3px;}
.metric .k{text-transform: uppercase; font-size: 10px; color: rgba(0, 0, 0, 0.55);}
.metric .v{margin-top: 10px; font-size: 28px; color: rgb(5, 5, 5);}
@media (max-width: 1180px){.dual-stream{grid-template-columns: 1fr;}}
@media (max-width: 760px){.shell{width: min(100% - 18px, 1600px);}}
@media (max-width: 760px){.ledger-panel, .monitor{padding-left: 0px; padding-right: 0px;}}
@media (max-width: 760px){.section-h{flex-direction: column; align-items: flex-start;}}
@media (max-width: 760px){.monitor{grid-template-columns: 1fr;}}
@media (max-width: 760px){.monitor .pane{border-right-width: medium; border-right-style: none; border-right-color: currentcolor; border-bottom: 1px solid rgba(0, 0, 0, 0.08);}}
@media (max-width: 760px){.monitor .pane:last-child{border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor;}}
h2, h3{font-size: inherit; font-weight: inherit;}
strong{font-weight: bolder;}
h2, h3, p{margin: 0px;}
svg{display: block; vertical-align: middle;}
.mt-5{margin-top: 1.25rem;}
.text-\[10px\]{font-size: 10px;}
.uppercase{text-transform: uppercase;}
.tracking-\[0\.34em\]{letter-spacing: 0.34em;}
.text-black{--tw-text-opacity: 1; color: rgb(0 0 0 / var(--tw-text-opacity, 1));}
