.mono{font-family: "IBM Plex Mono", monospace;}
.display{font-weight: 900;}
.telemetry{padding: 110px 0px; background: linear-gradient(rgb(15, 17, 20) 0%, rgb(17, 21, 26) 100%); color: white;}
.telemetry-shell{width: min(1600px, 100% - 28px); margin: 0px auto;}
.telemetry-head{display: flex; justify-content: space-between; gap: 20px; align-items: flex-end; margin-bottom: 28px;}
.telemetry-head h2{font-size: clamp(2.7rem, 5.4vw, 5.6rem); line-height: 0.88;}
.telemetry-head p{max-width: 440px; color: rgba(255, 255, 255, 0.66); line-height: 1.95;}
.grid-board{display: grid; grid-template-columns: repeat(12, 1fr); gap: 16px;}
.tile{grid-column: span 4; min-height: 220px; padding: 20px; border: 1px solid rgba(255, 255, 255, 0.08); background: linear-gradient(rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02)); border-radius: 3px; position: relative; overflow: hidden; opacity: 0; transform: translateY(24px); transition: opacity 0.6s, transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);}
.tile.in{opacity: 1; transform: translateY(0px);}
.tile::before{content: ""; position: absolute; inset: 0px; background: linear-gradient(90deg, rgba(73, 136, 255, 0.18), transparent 60%), linear-gradient(rgba(255, 255, 255, 0.04), transparent 25%); pointer-events: none;}
.tile .t{display: flex; justify-content: space-between; align-items: center; text-transform: uppercase; font-size: 10px; color: rgba(255, 255, 255, 0.55);}
.tile h3{margin-top: 18px; font-size: clamp(1.6rem, 2.8vw, 2.8rem); line-height: 0.95; color: white;}
.tile p{margin-top: 14px; color: rgba(255, 255, 255, 0.68); line-height: 1.85; max-width: 42ch; font-size: 14px;}
.tile svg{width: 100%; height: 84px; margin-top: 16px; overflow: visible;}
.tile.wide{grid-column: span 8;}
.tile.tall{min-height: 278px;}
.telemetry-foot{margin-top: 16px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px;}
.signal{padding: 18px 20px; border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.03); border-radius: 3px;}
.signal .name{text-transform: uppercase; font-size: 10px; color: rgba(255, 255, 255, 0.52);}
.signal .value{margin-top: 10px; font-size: 30px;}
@media (max-width: 1180px){.grid-board{grid-template-columns: repeat(6, 1fr);}}
@media (max-width: 1180px){.tile, .tile.wide{grid-column: span 6;}}
@media (max-width: 1180px){.telemetry-foot{grid-template-columns: 1fr;}}
@media (max-width: 760px){.telemetry-shell{width: min(100% - 18px, 1600px);}}
@media (max-width: 760px){.telemetry-head{flex-direction: column; align-items: flex-start;}}
@media (max-width: 760px){.grid-board{grid-template-columns: 1fr;}}
@media (max-width: 760px){.tile, .tile.wide{grid-column: span 1;}}
